def create_draft_profiles(apps, schema_editor):
    """Publication is explicit opt-in: every school starts in DRAFT, so none is public."""
    School = apps.get_model('schools', 'School')
    Profile = apps.get_model('schools', 'SchoolPublicProfile')
    existing = set(Profile.objects.values_list('school_id', flat=True))
    missing = [Profile(school_id=sid, publication_status='draft')
               for sid in School.objects.values_list('id', flat=True) if sid not in existing]
    Profile.objects.bulk_create(missing, batch_size=500)


